command:
$ErrorActionPreference="Stop"
Set-Location -LiteralPath $env:FLYEXPLORER_CANONICAL_CHECKOUT
& git fetch origin main work/search-v3-indexed-filename-20261008 --no-tags
if($LASTEXITCODE -ne 0){throw "fetch"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne "387efa622f6a9ce6685e3bffb98299df0503de3c"){throw "main moved"}
if((& git rev-parse refs/remotes/origin/work/search-v3-indexed-filename-20261008).Trim() -ne "aa61e28cb5f3a12cd90f59f022da4b6111ce9e6b"){throw "candidate moved"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){throw "canonical checkout dirty"}
& git diff --quiet ffc2466be51c32c1cf7454a2df80fe4f8c3f5f99 aa61e28cb5f3a12cd90f59f022da4b6111ce9e6b -- app/winui src/base tests/winui
if($LASTEXITCODE -ne 0){throw "accepted product or test source changed"}
try {
 & git switch --detach aa61e28cb5f3a12cd90f59f022da4b6111ce9e6b
 if($LASTEXITCODE -ne 0){throw "candidate checkout failed"}
 & .\test.bat policy
 if($LASTEXITCODE -ne 0){throw "policy failed"}
 & git diff --check 387efa622f6a9ce6685e3bffb98299df0503de3c aa61e28cb5f3a12cd90f59f022da4b6111ce9e6b
 if($LASTEXITCODE -ne 0){throw "diff check failed"}
 Write-Host "SEARCH_V3_INDEXED_FINAL_POLICY=PASS"
} finally {
 & git switch main
 if($LASTEXITCODE -ne 0){throw "restore main failed"}
 & git merge --ff-only origin/main
 if($LASTEXITCODE -ne 0){throw "restore main ff failed"}
}
